std::cout << "Filter Pages Read: " << filterPagesRead << std::endl;
std::cout << "Aggregate Pages Read: " << aggregatePagesRead << std::endl;
std::cout << "Total Columnar Storage Pages Read: " << (filterPagesRead + aggregatePagesRead) << std::endl;
```

